"""Build the bilingual, embedded educational catalogue from authored source data."""
from pathlib import Path
import xml.etree.ElementTree as E
catalog=E.Element('catalog',version='1')
def pair(s):
 a,b=s.split('~');return a,b
def cat(cid,name,description,rows):
 c=E.SubElement(catalog,'category',id=cid,it=pair(name)[0],en=pair(name)[1],descriptionIt=pair(description)[0],descriptionEn=pair(description)[1])
 for i,line in enumerate(rows.strip().splitlines()):
  fields=line.split('|');assert len(fields)==6,(cid,i,line)
  q=E.SubElement(c,'question',id=f'{cid}-{i+1:02}',level=str(1+i//5),source='anatomy')
  for tag,value in [('prompt',fields[0]),('explanation',fields[5])]:
   it,en=pair(value);E.SubElement(q,tag,it=it,en=en)
  for j,opt in enumerate(fields[1:5]):
   it,en=pair(opt);E.SubElement(q,'option',id=str(j),correct=str(j==0).lower(),it=it,en=en)
 assert i==9,cid
